from render import *
from matching import views
def main():
    vv=views();new=[c for c in cases()if c.get('new_reference')];records=load(R/'metrics/new_reference_sources.json');overlaps=[];validation=[]
    for c in new:
        s=source(c['id']);q=next(r for r in records if r['reference']==c['id']);plan=next(x for x in load(R/'metrics/new_reference_plan.json')if x['reference_view']==q['reference_view']);older=source(plan['historical_case']);t=dict(id=c['reference'],RGB=c['RGB'],Mask=c['Mask'],K=s['p']['K'],c2w=s['p']['pose'],ring_case=c['id']);old=projection(older['P'],older['C'],t);m=metric(old,t);overlaps.append(dict(reference=c['id'],group=c['group'],old_reference=plan['historical_case'],preselected_direction_gap_deg=plan['angular_gap_to_old_deg'],old_to_new_source_mask_coverage=m['coverage'],old_visible_on_new_mask_pixels=m['covered_N'],new_source_mask_denominator=m['target_Polyp_N'],comparison_identity='visibility diagnostic; not new true surface area',camera_identity=c['camera_identity']))
        held=[v for v in vv.values()if v['source_id']==c['group']+'_video'+c['video']and v.get('role')=='HOLDOUT'];ids=np.load(R/f'local_results/cleaned/{c["id"]}.npz')['kept_original_ids']
        if held:
            held.sort(key=lambda v:v['index']);v=held[0];t=dict(v,id=v['id'],ring_case=c['id']);r=projection(s['P'],s['C'],t);p=projection(s['P'][ids],s['C'][ids],t,ids);validation.append(dict(reference=c['id'],group=c['group'],target=v['id'],role='FROZEN_HELD_FRAME_NOT_USED_IN_NEW_HERO; old full pipeline not a new blind test',Raw=metric(r,t),Cleaned=metric(p,t),common=common_metric(r,p,t)));folder=R/'local_results/new_reference_validation';folder.mkdir(exist_ok=True);np.savez_compressed(folder/(c['id']+'.npz'),Raw_RGBA=r['RGBA'],Cleaned_RGBA=p['RGBA'],Raw_layer=r['layer'],Cleaned_layer=p['layer'])
        else:validation.append(dict(reference=c['id'],group=c['group'],status='NOT_EVALUABLE_NO_FROZEN_HOLDOUT_CAMERA',target=None))
